# Intermediate unit 3 – Particles in phrasal verbs. Bám sách: trang 10–11 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
theory = (
 P("A particle is either a preposition (<i>from, to, with</i>) or an adverb (<i>out, up, about</i>). Adding different particles to one basic verb creates different phrasal verbs.", "Tiểu từ là giới từ (<i>from, to, with</i>) hoặc trạng từ (<i>out, up, about</i>). Gắn các tiểu từ khác nhau vào cùng một động từ sẽ tạo ra các phrasal verb khác nhau.")
 + H("A", "What do particles mean?", "Tiểu từ mang nghĩa gì?")
 + P("Sometimes the particle has a clear basic meaning. With <i>invite</i>, the particle shows what the person actually said:", "Có khi tiểu từ mang nghĩa gốc rất rõ. Với <i>invite</i>, tiểu từ cho thấy người mời thực sự đã nói gì:")
 + T([
    ("<b>invite out</b>", "Jack: ‘Let’s go out together.’", "Jack: ‘Mình đi chơi nhé.’"),
    ("<b>invite in</b>", "Rosie: ‘Please come in!’", "Rosie: ‘Mời vào nhà!’"),
    ("<b>invite over</b> / <b>invite round</b>", "Molly: ‘Come to our place.’ Alex: ‘Come to my house for dinner or a drink.’", "Molly: ‘Đến nhà mình chơi.’ Alex: ‘Đến nhà mình ăn tối hay uống chút gì nhé.’"),
    ("<b>invite up</b>", "James: ‘Come upstairs to my flat.’", "James: ‘Lên căn hộ của mình trên lầu đi.’"),
    ("<b>invite along</b>", "Mia: ‘Come with us!’", "Mia: ‘Đi cùng bọn mình nhé!’"),
    ("<b>invite back</b>", "Stan: ‘Come back home with me.’", "Stan: ‘Về nhà mình đi.’"),
 ], head=("Phrasal verb", "What the speaker said", "Người mời đã nói"))
 + H("B", "What other meanings can particles have?", "Tiểu từ còn có nghĩa nào khác?")
 + P("Most particles have several senses. <i>Over</i>, for example, can show (a) a change of position – <b>fall over</b> (fall to the ground), <b>move over</b> (move to make room for someone); or (b) thoroughness – <b>read over</b> (read carefully), <b>talk over</b> (discuss fully before deciding). Units 13–21 look at particles in more detail.", "Hầu hết tiểu từ có nhiều nghĩa. Ví dụ <i>over</i> có thể chỉ (a) đổi vị trí – <b>fall over</b> (ngã xuống đất), <b>move over</b> (dịch chỗ nhường cho người khác); hoặc (b) sự kỹ lưỡng – <b>read over</b> (đọc kỹ), <b>talk over</b> (bàn kỹ trước khi quyết). Bài 13–21 nói kỹ hơn về tiểu từ.")
 + H("C", "Where does the particle go?", "Tiểu từ đứng ở đâu?")
 + T([
    ("<b>look for</b> my keys", "particle before the object only (not: look my keys for)", "tiểu từ chỉ đứng trước tân ngữ"),
    ("<b>have</b> a lot of work <b>on</b>", "particle after the object only (not: have on a lot of work)", "tiểu từ chỉ đứng sau tân ngữ"),
    ("<b>wake up</b> the children / <b>wake</b> the children <b>up</b>", "either position; with a pronoun the particle must follow it: woke them up", "đứng trước hay sau đều được; với đại từ thì tiểu từ phải đứng sau: woke them up"),
 ], head=("Example", "Position of the particle", "Vị trí tiểu từ"))
)
def INV(part, said_en, said_vi, d_en, d_vi, gl, ex_en, ex_vi, note, coll, syn, ant):
    w = f"invite {part} somebody"
    return PV(w, "phr.v.", "neutral", d_en, f"/ɪnˌvaɪt ˈ{ {'out':'aʊt','in':'ɪn','over':'əʊvə','round':'raʊnd','up':'ʌp','along':'əlɒŋ','back':'bæk'}[part]} ˈsʌmbədi/".replace("ˈəlɒŋ","əˈlɒŋ"),
      d_vi, gl, ex_en, ex_vi, SEP(f"invite {part} a friend", f"invite Jack {part}", f"invite me {part}"),
      f"Mục A: lời mời gốc – {said_vi}. " + note, coll, f"đặt đại từ sau tiểu từ (<i>invite {part} me</i>).", syn, ant)
